import {Pressable,StyleSheet,Text,View} from '@/platform/react-native';import {router} from '@/router';import {useQuery} from '@tanstack/react-query';import {Ionicons} from '@/platform/icons';import {api} from '@/lib/api';import {Card,EmptyState,Header,Muted,Screen,useAppTheme} from '@/components/UI';
export default function Events(){const{palette}=useAppTheme();const q=useQuery<any[]>({queryKey:['all-events'],queryFn:async()=>(await api.get('/me/events')).data});return <Screen scroll><Header title="Upcoming Events" subtitle="Meetings and events across all your communities"/>{q.data?.length?q.data.map(x=><Pressable key={`${x.ItemType}-${x.Id}`} onPress={()=>router.push(`/community/${x.CommunityId}/${x.ItemType==='EVENT'?'events':'meetings'}` as any)}><Card style={s.row}><View style={[s.date,{borderColor:palette.success}]}><Text style={{color:palette.success,fontWeight:'900'}}>{new Date(x.DueAt).toLocaleString('en',{month:'short'}).toUpperCase()}</Text><Text style={[s.day,{color:palette.text}]}>{new Date(x.DueAt).getDate()}</Text></View><View style={{flex:1}}><Text style={[s.title,{color:palette.text}]}>{x.Title}</Text><Muted>{x.CommunityName}</Muted><Muted>{new Date(x.DueAt).toLocaleString()} · {x.Location||'Location not specified'}</Muted></View><Ionicons name="chevron-forward" size={20} color={palette.muted}/></Card></Pressable>):q.isLoading?<Muted>Loading events…</Muted>:<EmptyState icon="calendar-outline" title="No upcoming events" body="Events and meetings from your communities will appear here."/>}</Screen>};
const s=StyleSheet.create({row:{flexDirection:'row',alignItems:'center',gap:13},date:{width:58,height:61,borderWidth:1,borderRadius:10,alignItems:'center',justifyContent:'center'},day:{fontSize:22,fontWeight:'900'},title:{fontWeight:'900',marginBottom:4}});
